bypat=collections.defaultdict(list)
for t in TYPES:
    if t=='Patient': continue
    for r in res[t]:
        s=subj(r)
        if s: bypat[s].append(r)

def fmt(r):
    t=r['resourceType']; i=r['id']; e=et(r)
    if t=='EpisodeOfCare': return f"[{e}] EpisodeOfCare {i} start={r['period']['start']} status={r['status']}"
    if t=='Condition': return f"[{e}] Condition {i} '{r['code']['text']}' recorded={r.get('recordedDate')} by {r.get('recorder',{}).get('display')}"
    if t=='AllergyIntolerance':
        rx=[x.get('manifestation',[{}])[0].get('text') for x in r.get('reaction',[])]
        return f"[{e}] Allergy {i} {r['code']['text']} reaction={rx} crit={r.get('criticality')} note={[n['text'] for n in r.get('note',[])]}"
    if t=='Specimen':
        return (f"[{e}] Specimen {i} acc={r.get('accessionIdentifier',{}).get('value')} coll={r['collection'].get('collectedDateTime')} "
                f"by {r['collection'].get('collector',{}).get('display')} label: {ext(r,'label-name')} / MRN {ext(r,'label-mrn')} / DOB {ext(r,'label-dob')}"
                + (f" note={[n['text'] for n in r.get('note',[])]}" if r.get('note') else ''))
    if t=='Observation':
        sp=r.get('specimen',{}).get('reference','').split('/')[-1]
        acc=r.get('identifier',[{}])[0].get('value')
        notes=[n['text'] for n in r.get('note',[])]
        return (f"[{e}] Obs {i} '{r['code']['text']}' coll={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} "
                f"value={r.get('valueString')!r} spec={sp} acc={acc}"+(f" NOTE={notes}" if notes else ''))
    if t=='MedicationAdministration':
        return (f"[{e}] MedAdmin {i} {r['medicationCodeableConcept']['text']} dose='{r.get('dosage',{}).get('text')}' when={r.get('effectiveDateTime')} "
                f"status={r['status']} perf={[p['actor']['display'] for p in r.get('performer',[])]}"+(f" note={[n['text'] for n in r.get('note',[])]}" if r.get('note') else '')
                + (f" reasonNotGiven={r.get('statusReason')}" if r.get('statusReason') else ''))
    if t=='MedicationDispense':
        return (f"[{e}] MedDispense {i} {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} "
                f"handed={r.get('whenHandedOver')} sig='{r.get('dosageInstruction',[{}])[0].get('text')}' note={[n['text'] for n in r.get('note',[])]}")
    if t=='DocumentReference':
        return (f"[{e}] Doc {i} type='{r['type']['text']}' date={r.get('date')} author={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')} status={r.get('docStatus')}\n    TEXT: "
                + r.get('description','').replace('\n','\n    '))
    if t=='Task':
        return f"[{e}] Task {i} status={r['status']} code={r.get('code',{}).get('coding',[{}])[0].get('code')} focus={r.get('focus',{}).get('reference')} desc={r.get('description')}"
    return f"[{e}] {t} {i} "+json.dumps(r)[:300]

def basic_fmt(b):
    return (f"[{et(b)}] Accession {b['id']} acc={ext(b,'accession')} name={ext(b,'patient-name')} MRN={ext(b,'patient-mrn')} DOB={ext(b,'patient-dob')} recv={ext(b,'received')} by {b.get('author',{}).get('display')}")

def chart(pid):
    p=pats[pid]
    out=[]
    out.append(f"=== {pid} {p['name'][0]['text']} MRN={p['identifier'][0]['value']} DOB={p['birthDate']} sex={p['gender']}")
    items=sorted(bypat[pid],key=lambda r:(et(r),r['resourceType']))
    accs=set()
    for r in items:
        out.append(fmt(r))
        if r['resourceType']=='Specimen' and r.get('accessionIdentifier'): accs.add(r['accessionIdentifier']['value'])
        if r['resourceType']=='Observation' and r.get('identifier'): accs.add(r['identifier'][0]['value'])
    out.append('-- accessioning entries --')
    for a in sorted(accs):
        for b in acc_basic.get(a,[]): out.append(basic_fmt(b))
    return '\n'.join(out)

if __name__=='__main__':
    ids=sys.argv[1:] or sorted(pats)
    for pid in ids: print(chart(pid)); print()
