def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k in ('valueDateTime','valueString','valueDate','valueCode'):
                if k in e: return e[k]
def et(r): return ext(r,'event-time') or ''
pats={p['id']:p for p in res['Patient']}
bymrn_dob={(p['identifier'][0]['value'],p['birthDate']):p['id'] for p in res['Patient']}
EVAL=datetime.datetime(2026,9,24,12,0)
def dt(s):
    if not s: return None
    s=s.replace('Z','')
    try: return datetime.datetime.fromisoformat(s)
    except: return datetime.datetime.fromisoformat(s+'T00:00:00')
acc_basic=collections.defaultdict(list)
for b in res['Basic']: acc_basic[ext(b,'accession')].append(b)
spec={s['id']:s for s in res['Specimen']}
def subj(r):
    s=r.get('subject') or r.get('patient') or r.get('for')
    return s['reference'].split('/')[-1] if s else None
bypat=collections.defaultdict(lambda: collections.defaultdict(list))
for t in TYPES:
    if t in ('Patient','Basic'): continue
    for r in res[t]:
        s=subj(r)
        if s: bypat[s][t].append(r)
eps={e['id']:e for e in res['EpisodeOfCare']}

def ident(mrn,dob):
    return bymrn_dob.get((mrn,dob))

rows=[]
for pid,p in sorted(pats.items()):
    ch=bypat[pid]
    ep=ch['EpisodeOfCare'][0]
    dx=dt(ep['period']['start'])
    conds=[(c['code']['text'],c.get('recordedDate')) for c in sorted(ch['Condition'],key=et)]
    meds=[(m.get('effectiveDateTime'),m['medicationCodeableConcept']['text'][:12],m.get('dosage',{}).get('text'),m['status']) for m in sorted(ch['MedicationAdministration'],key=et)]
    disp=[(d.get('whenHandedOver'),d['medicationCodeableConcept']['text'][:20],d.get('quantity',{}).get('value'),d.get('daysSupply',{}).get('value')) for d in ch['MedicationDispense']]
    rprs=[]
    idflags=[]
    for o in sorted(ch['Observation'],key=et):
        code=o['code']['text']
        sp=spec.get(o.get('specimen',{}).get('reference','').split('/')[-1])
        lab=(ext(sp,'label-mrn'),ext(sp,'label-dob'),ext(sp,'label-name')) if sp else None
        accs=acc_basic.get((o.get('identifier') or [{}])[0].get('value'),[])
        ac=[(ext(b,'patient-mrn'),ext(b,'patient-dob'),ext(b,'patient-name')) for b in accs]
        labp=ident(lab[0],lab[1]) if lab else None
        accp=[ident(a[0],a[1]) for a in ac]
        mismatch=''
        if lab and (labp!=pid or any(x!=pid for x in accp)):
            mismatch=f"LABEL->{labp}({lab[0]},{lab[1]},{lab[2]}) ACC->{accp}{ac}"
            idflags.append((o['id'],code,o.get('effectiveDateTime'),mismatch))
        if 'RPR' in code or 'VDRL' in code:
            rprs.append((sp['collection']['collectedDateTime'] if sp else o.get('effectiveDateTime'),o['status'],o.get('valueString'),o['id'],[n['text'] for n in o.get('note',[])],mismatch))
    hcg=[(o.get('effectiveDateTime'),o['status'],o.get('valueString')) for o in ch['Observation'] if 'hCG' in o['code']['text']]
    allerg=[a['code']['text'] for a in ch['AllergyIntolerance']]
    docs=[(d['type']['text'],d.get('date'),d.get('description','')) for d in sorted(ch['DocumentReference'],key=et)]
    tasks=[t['code']['coding'][0]['code'] for t in ch['Task']]
    rows.append(dict(pid=pid,ep=ep['id'],dx=dx,conds=conds,meds=meds,disp=disp,rprs=rprs,hcg=hcg,allerg=allerg,docs=docs,tasks=tasks,idflags=idflags,sex=p['gender']))
json.dump([{**r,'dx':r['dx'].isoformat()} for r in rows],open('/tmp/rows.json','w'),indent=0)
# triage print
for r in rows:
    print(f"## {r['pid']} {r['ep']} dx={r['dx'].date()} sex={r['sex']} stage={[c[0] for c in r['conds']]} tasks={r['tasks']} allergy={r['allerg']}")
    print("   meds:",r['meds'],"disp:",r['disp'])
    print("   rpr:",[(x[0],x[1],x[2],x[4],x[5]) for x in r['rprs']])
    if r['hcg']: print("   hcg:",r['hcg'])
    if r['idflags']: print("   IDFLAG:",r['idflags'])
    print("   docs:",[(d[0],d[1][:10]) for d in r['docs']])
