obs=ld('Observation');sp={s['id']:s for s in ld('Specimen')};bs=ld('Basic');pats={p['id']:p for p in ld('Patient')}
eps={e['patient']['reference'].split('/')[-1]:e['id'] for e in ld('EpisodeOfCare')}
def ext(r,n):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+n): return e.get('valueDateTime') or e.get('valueString') or e.get('valueDate') or e.get('valueCode')
accs=collections.defaultdict(list)
for b in bs: accs[ext(b,'accession')].append(b)
bymd={(p['identifier'][0]['value'],p['birthDate']):p['id'] for p in pats.values()}
# corrections
LABEL_CORR={'R67e0bc76cea5':('93952483','1990-11-21','IBARRA, KOFI'),
            'R010a690195fe':('69252139','2001-01-17','NAVARRO, ROSA'),
            'Ra4e4041a08cb':('78271500','1968-07-17','JARAMILLO, KENDRA')}
ACC_CORR={'R06ac3e96c815':('17267553','1987-11-20','RASMUSSEN, ELENA'),
          'R6ac4dfb8d85d':('53042841','1987-01-12','WHITAKER, YOSEF'),
          'R802e715c2a32':('67699419','1965-05-24','UMEH, BRANDON')}
rows=[]
for o in obs:
    P=o['subject']['reference'].split('/')[-1]
    s=sp[o['specimen']['reference'].split('/')[-1]]
    lm,ldb=(LABEL_CORR[s['id']][:2] if s['id'] in LABEL_CORR else (ext(s,'label-mrn'),ext(s,'label-dob')))
    lab=bymd.get((lm,ldb),('EXT:'+lm+'/'+ldb))
    ids={lab}
    accinfo=[]
    for b in accs.get((o.get('identifier') or [{}])[0].get('value'),[]):
        am,adb = (ACC_CORR[b['id']][:2] if b['id'] in ACC_CORR else (ext(b,'patient-mrn'),ext(b,'patient-dob')))
        a=bymd.get((am,adb),('EXT:'+am+'/'+adb)); ids.add(a); accinfo.append((b['id'],a))
    if ids=={P}: continue
    disp='confirmed' if P not in ids else 'cannot_determine'
    rows.append((P,eps[P],o['id'],o['code']['text'],o.get('effectiveDateTime','')[:10],disp,lab,accinfo,s['id']))
rows.sort()
for r in rows: print(r)
print(len(rows), 'patients:',len({r[0] for r in rows}))
