              f"The specimen collection record {s['id']} is labeled {lname} (MRN {lm}, DOB {ldb}), this patient, while the {accdesc}. "
              f"No signed correction by the author of either record resolves the discrepancy, so the specimen's patient is unresolved and it cannot be determined whether the result belongs to a different patient.")
        items.append(dict(patient=P,episode=eps[P],issue='MISFILED_RESULT',disposition='cannot_determine',missing_evidence='UNRESOLVED_SOURCE_CONFLICT',evidence=ev,explanation=expl))
json.dump(items,open('/tmp/sub/items_mis.json','w'),indent=1)
