import json,collections
A=json.load(open('items_mis.json'))+json.load(open('items_rest.json'))
def ld(t): return [json.loads(l) for l in open('/tmp/export/'+t+'.ndjson')]
TYPES=['AllergyIntolerance','Basic','Condition','DocumentReference','EpisodeOfCare','MedicationAdministration','MedicationDispense','Observation','Patient','Specimen','Task']
allids={}
for t in TYPES:
    for r in ld(t): allids[r['id']]=(t,(r.get('subject') or r.get('patient') or r.get('for') or {}).get('reference'))
eps={e['id']:e['patient']['reference'].split('/')[-1] for e in ld('EpisodeOfCare')}
print('items',len(A))
k=collections.Counter((i['patient'],i['issue']) for i in A)
print('dups',[x for x,c in k.items() if c>1])
for i in A:
    assert eps[i['episode']]==i['patient'], i
    for e in i['evidence']:
        if e not in allids: print('MISSING',i['patient'],i['issue'],e)
    assert 1<=len(i['evidence'])<=30
    assert i['explanation'] and len(i['explanation'])<=4000
    if i['disposition']=='cannot_determine': assert i['missing_evidence'] in ('RESULT_PENDING','OUTSIDE_RECORD_NOT_RECEIVED','UNRESOLVED_SOURCE_CONFLICT')
    else: assert i['missing_evidence'] is None
print(collections.Counter((i['issue'],i['disposition']) for i in A))
# check requests answered
reqs=[r for r in ld('Task') if r['status']=='requested']
have={(i['patient'],i['issue']) for i in A}
for r in reqs:
    key=(r['for']['reference'].split('/')[-1],r['code']['coding'][0]['code'])
    if key not in have: print('UNANSWERED REQUEST',r['id'],key)
json.dump(A,open('all_items.json','w'),indent=1)
